import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.iphy.genericiphy import GenericIphy

__author__ = 'Bartlomiej 1. Kopacz'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'bartlomiej.1.kopacz@nokia.com'


class IRFHeadExe(GenericIphy):
    """Irfheadexe command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, options=None, runner=None):
        """
        Irfheadexe command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param options: Options of IPHY FCT IRFHeadExe command
        :param runner: Runner to run command
        """
        super(IRFHeadExe, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.current_ret["Success"] = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = '/opt/IRFHeadExe/IRFHeadExe'
        if self.options:
            cmd = f'{cmd} {self.options}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_xml_file_name(line)
                self._parse_state(line)
                self._parse_version(line)
                self._parse_exception(line)
            except ParsingDone:
                pass
        return super(IRFHeadExe, self).on_new_line(line, is_full_line)

    # Checking file /rom/simmode/iphy.xml --> /flash/simmode/iphy-3frgp-3cells-12-2txrx.xml
    _re_xml_file_name = re.compile(r"^Checking.*-->\s(?P<XML_FILE_NAME>.*\.xml)")

    def _parse_xml_file_name(self, line):
        if self._regex_helper.search_compiled(IRFHeadExe._re_xml_file_name, line):
            xml_file_name = self._regex_helper.group("XML_FILE_NAME")
            self.current_ret["xml_file_name"] = xml_file_name.split("/")[-1]
            raise ParsingDone

    # Configuration file check OK
    _re_state = re.compile(r"^Configuration file check OK$")

    def _parse_state(self, line):
        if self._regex_helper.search_compiled(IRFHeadExe._re_state, line):
            self.current_ret["Success"] = True
            raise ParsingDone

    # WTS: WTS_1070199.2_4.0.7180
    _re_version = re.compile(r"^WTS:\s(?P<VERSION>.*)$")

    def _parse_version(self, line):
        if self._regex_helper.search_compiled(IRFHeadExe._re_version, line):
            version = self._regex_helper.group("VERSION")
            self.current_ret["version"] = version
            raise ParsingDone

    # caught exception: 'File iphy-3fxfa-3cells-3xABIA-CIPET.xml not found!'
    _re_exception = re.compile(r"^caught exception:\s'(?P<EXCEPTION>.*)'$")

    def _parse_exception(self, line):
        if self._regex_helper.search_compiled(IRFHeadExe._re_exception, line):
            exception = self._regex_helper.group("EXCEPTION")
            self.current_ret["exception"] = exception
            raise ParsingDone


